begin;
do $$
declare uid uuid:=gen_random_uuid(); other_id uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(uid,'clear-test-'||uid::text||'@example.invalid'),(other_id,'clear-test-'||other_id::text||'@example.invalid');
 perform set_config('request.jwt.claim.sub',uid::text,true);
 perform set_config('test.other_id',other_id::text,true);
 insert into public.expenses(user_id,category,amount,expense_date) values(other_id,'Other account test',7,current_date);
end $$;
set local role authenticated;
do $$
declare preview jsonb; result jsonb; expense_id uuid; receipt_id uuid; invoice_id uuid; before_number int; caught boolean:=false; uid uuid:=auth.uid();
begin
 insert into public.expenses(user_id,category,amount,expense_date) values(uid,'Test',100,current_date) returning id into expense_id;
 insert into public.income(user_id,source,amount,earned_on) values(uid,'Test',200,current_date);
 insert into public.mileage(user_id,trip_date,business_miles,purpose) values(uid,current_date,12,'Test');
 insert into public.receipts(user_id,expense_id,file_path,ai_status) values(uid,expense_id,uid::text||'/clear-test.jpg','failed') returning id into receipt_id;
 insert into public.vat_profiles(user_id,registered,vat_number,registration_date,scheme) values(uid,true,'123456789',current_date-1,'standard');
 insert into public.vat_purchases(expense_id,user_id,tax_point,paid_on,scheme,supplier_vat_number,vat_on_document,business_percent,claim_amount,evidence_confirmed) values(expense_id,uid,current_date,current_date,'standard','123456789',10,100,10,true);
 insert into public.recurring_expenses(user_id,category,amount,frequency,start_date) values(uid,'Test',10,'monthly',current_date);
 insert into public.tax_reserve(user_id,amount,saved_on,method) values(uid,10,current_date,'Test');
 perform public.save_driver_invoice_draft(gen_random_uuid(),'{}'::jsonb,0);
 preview:=public.preview_record_clear();
 if (preview->'counts'->>'expenses')::int<>1 then raise exception 'Preview leaked or missed records'; end if;
 begin perform public.clear_selected_records(array['expenses'],preview->>'signature','WRONG'); exception when raise_exception then caught:=true; end;
 if not caught then raise exception 'Missing confirmation accepted'; end if;
 caught:=false;
 begin perform public.clear_selected_records(array['profiles'],preview->>'signature','DELETE'); exception when raise_exception then caught:=true; end;
 if not caught then raise exception 'Invalid choice accepted'; end if;
 insert into public.expenses(user_id,category,amount,expense_date) values(uid,'Changed',50,current_date);
 caught:=false;
 begin perform public.clear_selected_records(array['expenses'],preview->>'signature','DELETE'); exception when raise_exception then caught:=true; end;
 if not caught or (select count(*) from public.expenses where user_id=uid)<>2 then raise exception 'Stale review accepted'; end if;
 preview:=public.preview_record_clear();
 result:=public.clear_selected_records(array['receipts'],preview->>'signature','DELETE');
 if exists(select 1 from public.receipts where user_id=uid) or not exists(select 1 from public.expenses where id=expense_id) then raise exception 'Receipt-only selection failed'; end if;
 if not exists(select 1 from public.receipt_cleanup_queue where user_id=uid and file_path=uid::text||'/clear-test.jpg') then raise exception 'File cleanup was not queued'; end if;
 preview:=public.preview_record_clear();
 result:=public.clear_selected_records(array['expenses'],preview->>'signature','DELETE');
 if exists(select 1 from public.expenses where user_id=uid) then raise exception 'Expenses not cleared'; end if;
 if not exists(select 1 from public.income where user_id=uid) or not exists(select 1 from public.mileage where user_id=uid) then raise exception 'Unselected records changed'; end if;
 invoice_id:=public.create_driver_invoice(jsonb_build_object('seller_contact','test@example.invalid','seller_name','Test Seller','seller_address','Test address','customer_name','Test Customer','customer_address','Test address','invoice_date',current_date,'supply_date',current_date,'due_date',current_date,'items',jsonb_build_array(jsonb_build_object('description','Test work','quantity',1,'unit_price',100,'vat_rate',20)),'payment_details','Test payment','vat_enabled',true,'price_basis','exclusive'),gen_random_uuid());
 perform public.pay_driver_invoice(invoice_id,current_date,null);
 select last_number into before_number from public.invoice_counters where user_id=uid;
 preview:=public.preview_record_clear();caught:=false;
 begin perform public.clear_selected_records(array['income'],preview->>'signature','DELETE'); exception when raise_exception then caught:=true; end;
 if not caught or not exists(select 1 from public.invoices where id=invoice_id) then raise exception 'Invoice link guard failed'; end if;
 insert into public.period_entries(user_id,period_start,period_end,income_amount,expense_amount,business_miles) values(uid,current_date,current_date,300,0,12);
 preview:=public.preview_record_clear();caught:=false;
 begin perform public.clear_selected_records(array['mileage'],preview->>'signature','DELETE'); exception when raise_exception then caught:=true; end;
 if not caught then raise exception 'Catch-up dependency guard failed'; end if;
 preview:=public.preview_record_clear();
 result:=public.clear_selected_records(array['income','mileage','invoices','drafts','catchup','regular','reserve'],preview->>'signature','DELETE');
 if exists(select 1 from public.income where user_id=uid) or exists(select 1 from public.mileage where user_id=uid) then raise exception 'Remaining selected records not cleared'; end if;
 if exists(select 1 from public.recurring_expenses where user_id=uid) or exists(select 1 from public.invoice_drafts where user_id=uid) or exists(select 1 from public.tax_reserve where user_id=uid) or exists(select 1 from public.vat_purchases where user_id=uid) then raise exception 'Selected costs/drafts/reserve/VAT remained'; end if;
 if not exists(select 1 from public.vat_profiles where user_id=uid and registered) then raise exception 'VAT settings removed'; end if;
 if (select last_number from public.invoice_counters where user_id=uid)<>before_number then raise exception 'Invoice counter was reset'; end if;
 perform set_config('request.jwt.claim.sub',current_setting('test.other_id'),true);
 if (select count(*) from public.expenses where user_id=auth.uid())<>1 then raise exception 'Another account was affected'; end if;
 if exists(select 1 from public.receipt_cleanup_queue where user_id=uid) then raise exception 'Cleanup queue leaked'; end if;
end $$;
rollback;
